package com.northstarbank.console.service;import com.northstarbank.console.domain.*;import com.northstarbank.console.integration.TierClient;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.Instant;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import org.springframework.http.HttpStatus;
@Service public class PasswordResetService{private final ResetRepository resets;private final OutboxRepository outbox;private final TierClient tiers;private static final String[] ROLES={"csr","officer","supervisor","regional","headoffice","security"};private final SecureRandom random=new SecureRandom();public PasswordResetService(ResetRepository r,OutboxRepository o,TierClient t){resets=r;outbox=o;tiers=t;}@Transactional public boolean request(String email){String employee=lookup(email);if(employee==null)return false;byte[] bytes=new byte[32];random.nextBytes(bytes);String raw=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);PasswordResetToken token=new PasswordResetToken();token.tokenHash=hash(raw);token.employeeId=employee;token.expiresAt=Instant.now().plusSeconds(1800);resets.save(token);Outbox mail=new Outbox();mail.recipient=email;mail.subject="Reset your Northstar password";mail.body="http://localhost:8080/password-reset/"+raw;mail.status="pending";outbox.save(mail);return true;}@Transactional public String complete(String raw,String password){PasswordResetToken token=resets.findById(hash(raw)).filter(t->t.usedAt==null&&t.expiresAt.isAfter(Instant.now())).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Reset link is invalid or expired"));tiers.resetPassword(token.employeeId,password);token.usedAt=Instant.now();return ROLES[Integer.parseInt(token.employeeId.substring(3))-1]+"@northstar.test";}public boolean valid(String raw){return resets.findById(hash(raw)).filter(t->t.usedAt==null&&t.expiresAt.isAfter(Instant.now())).isPresent();}private String lookup(String email){for(int i=0;i<ROLES.length;i++)if(email.equalsIgnoreCase(ROLES[i]+"@northstar.test"))return String.format("EMP%03d",i+1);return null;}private String hash(String raw){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
